(7692232, 1260865, 122678, '<td valign="top">Beautiful image</td>', 'Beautiful image', '2021-04-21 08:33:05.000000', NULL, 1),
(7692247, 1260865, 53147, '<td valign="top">One of my top two faves of the challenge. The high contrast just works very well. Just a super pleasing image for me. If it were mine i would print it out and hang it.</td>', 'One of my top two faves of the challenge. The high contrast just works very well. Just a super pleasing image for me. If it were mine i would print it out and hang it.', '2021-04-21 09:27:24.000000', NULL, 1),
(7692248, 1260825, 53147, '<td valign="top">One of my top two faves for the challenge. love the black and white treatment. And happy you didn''t make a noise to get them all looking at you. All of them staring to the left makes it all the more intriguing.</td>', 'One of my top two faves for the challenge. love the black and white treatment. And happy you didn''t make a noise to get them all looking at you. All of them staring to the left makes it all the more intriguing.', '2021-04-21 09:29:51.000000', NULL, 1),
(7692262, 1260861, 53147, '<td valign="top">Love the colors. And the detail/sharpness kept i the face but the rest of the fur on the cats body looking almost like smooth flowing water is just lovely. I want to pet him.</td>', 'Love the colors. And the detail/sharpness kept i the face but the rest of the fur on the cats body looking almost like smooth flowing water is just lovely. I want to pet him.', '2021-04-21 12:24:56.000000', NULL, 1),
(7692264, 1260582, 53147, '<td valign="top">Love the lines and simplicity of the shot. And that the cat only takes up a handful of pixels in th image works well. Personally i would have probably over edited the image to make it "pop" some more but I still find it pleasing as it is.</td>', 'Love the lines and simplicity of the shot. And that the cat only takes up a handful of pixels in th image works well. Personally i would have probably over edited the image to make it "pop" some more but I still find it pleasing as it is.', '2021-04-21 12:26:26.000000', NULL, 1),
(7692265, 1260610, 65234, '<td valign="top">Terrific capture!!</td>', 'Terrific capture!!', '2021-04-21 12:28:43.000000', NULL, 1),
(7692266, 1260851, 65234, '<td valign="top">LOL! Don''t blame him in the slightest; the Cone of Shame is embarassing. The kitten is *adorable.*</td>', 'LOL! Don''t blame him in the slightest; the Cone of Shame is embarassing. The kitten is *adorable.*', '2021-04-21 12:29:44.000000', NULL, 1),
(7692267, 1260845, 65234, '<td valign="top">That''s what you get for sticking a camera in his face. Dramatic light.</td>', 'That''s what you get for sticking a camera in his face. Dramatic light.', '2021-04-21 12:30:15.000000', NULL, 1),
(7692268, 1260868, 65234, '<td valign="top">Framed by bokeh; very dramatic. Nicely composed. I might brighten up the cat''s face a little; he''s a bit overwhelmed by the bright, colorful background.</td>', 'Framed by bokeh; very dramatic. Nicely composed. I might brighten up the cat''s face a little; he''s a bit overwhelmed by the bright, colorful background.', '2021-04-21 12:34:10.000000', NULL, 1),
